-- Adaptation of NAXA Services stock movement pattern to inter-site lot transfer.
-- No revenue, purchase debt or cash entry is generated by this workflow.
begin;
create table public.zp_transfers(
 id uuid primary key default gen_random_uuid(),org_id uuid not null references public.zp_organizations(id),
 source_site uuid not null,destination_site uuid not null,source_lot uuid not null,destination_ingredient uuid not null,
 requested_by uuid not null,request_id uuid not null,qty_milli bigint not null check(qty_milli between 1 and 1000000000),
 state text not null default 'requested' check(state in ('requested','approved','in_transit','received','cancelled')),
 approved_by uuid,approved_at timestamptz,dispatched_by uuid,dispatched_at timestamptz,received_by uuid,received_at timestamptz,
 transferred_cost bigint check(transferred_cost>=0),expires_on date,source_label text,
 received_milli bigint check(received_milli between 0 and qty_milli),received_cost bigint check(received_cost between 0 and transferred_cost),
 destination_lot uuid unique,discrepancy_reason text,cancelled_by uuid,cancelled_at timestamptz,
 created_at timestamptz not null default now(),check(source_site<>destination_site),unique(requested_by,request_id),
 foreign key(source_site,org_id) references public.zp_site_modes(site_id,org_id),
 foreign key(destination_site,org_id) references public.zp_site_modes(site_id,org_id),
 foreign key(source_lot,org_id,source_site) references public.zp_ingredient_lots(id,org_id,site_id),
 foreign key(destination_ingredient,org_id,destination_site) references public.zp_ingredients(id,org_id,site_id),
 foreign key(destination_lot,org_id,destination_site) references public.zp_ingredient_lots(id,org_id,site_id),
 foreign key(requested_by,org_id) references public.zp_members(id,org_id),
 foreign key(approved_by,org_id) references public.zp_members(id,org_id),
 foreign key(dispatched_by,org_id) references public.zp_members(id,org_id),
 foreign key(received_by,org_id) references public.zp_members(id,org_id),
 foreign key(cancelled_by,org_id) references public.zp_members(id,org_id));
create function public.zp_transfer_actor(p_access text,p_site uuid) returns public.zp_members language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare m public.zp_members;begin m:=public.zp_erp_actor(p_access,p_site);
 if public.zp_paid_plan(m.org_id) is distinct from 'PREMIUM' then raise exception 'PREMIUM_REQUIRED';end if;return m;end $$;
create function public.zp_transfer_request(p_access text,p_site uuid,p_destination uuid,p_lot uuid,p_ingredient uuid,p_request uuid,p_qty bigint) returns uuid language plpgsql security invoker set search_path=pg_catalog,public as $$
declare m public.zp_members;d public.zp_members;x public.zp_transfers;i uuid;begin
 m:=public.zp_transfer_actor(p_access,p_site);d:=public.zp_transfer_actor(p_access,p_destination);
 if d.id<>m.id or p_destination=p_site then raise exception 'DENIED';end if;
 perform 1 from public.zp_site_modes where site_id=p_site and org_id=m.org_id for update;
 select * into x from public.zp_transfers where requested_by=m.id and request_id=p_request;
 if x.id is not null then if (x.source_site,x.destination_site,x.source_lot,x.destination_ingredient,x.qty_milli) is distinct from (p_site,p_destination,p_lot,p_ingredient,p_qty) then raise exception 'IDEMPOTENCY_CONFLICT';end if;return x.id;end if;
 if p_qty is null or p_qty not between 1 and 1000000000 or not exists(select 1 from public.zp_ingredient_lots l join public.zp_ingredients src on src.id=l.ingredient_id join public.zp_ingredients dst on dst.id=p_ingredient and dst.org_id=m.org_id and dst.site_id=p_destination where l.id=p_lot and l.org_id=m.org_id and l.site_id=p_site and src.unit=dst.unit and src.sku<>'' and src.sku=dst.sku) then raise exception 'TRANSFER_ITEM_MISMATCH';end if;
 insert into public.zp_transfers(org_id,source_site,destination_site,source_lot,destination_ingredient,requested_by,request_id,qty_milli) values(m.org_id,p_site,p_destination,p_lot,p_ingredient,m.id,p_request,p_qty) returning id into i;return i;end $$;
create function public.zp_transfer_decide(p_access text,p_site uuid,p_transfer uuid,p_decision text) returns text language plpgsql security invoker set search_path=pg_catalog,public as $$
declare m public.zp_members;x public.zp_transfers;begin m:=public.zp_transfer_actor(p_access,p_site);
 if m.role_code<>'promoteur' then raise exception 'DENIED';end if;
 select * into x from public.zp_transfers where id=p_transfer and org_id=m.org_id and source_site=p_site for update;if x.id is null then raise exception 'DENIED';end if;
 if p_decision='approved' then
 if x.state='approved' then return x.state;end if;
 if x.state<>'requested' then raise exception 'INVALID_TRANSITION';end if;
 update public.zp_transfers set state='approved',approved_at=now(),approved_by=m.id where id=x.id;
 elsif p_decision='cancelled' then
 if x.state='cancelled' then return x.state;end if;
 if x.state not in ('requested','approved') then raise exception 'INVALID_TRANSITION';end if;
 update public.zp_transfers set state='cancelled',cancelled_at=now(),cancelled_by=m.id where id=x.id;
 else raise exception 'INVALID_TRANSITION';end if;return p_decision;end $$;
create function public.zp_transfer_dispatch(p_access text,p_site uuid,p_transfer uuid) returns text language plpgsql security invoker set search_path=pg_catalog,public as $$
declare m public.zp_members;x public.zp_transfers;l public.zp_ingredient_lots;c bigint;begin m:=public.zp_transfer_actor(p_access,p_site);
 perform 1 from public.zp_site_modes where site_id=p_site for update;
 select * into x from public.zp_transfers where id=p_transfer and org_id=m.org_id and source_site=p_site for update;if x.id is null then raise exception 'DENIED';end if;
 if x.state='in_transit' then return x.state;end if;if x.state<>'approved' then raise exception 'INVALID_TRANSITION';end if;
 if not exists(select 1 from public.zp_sites where id=x.destination_site and org_id=m.org_id and active) then raise exception 'DENIED';end if;
 select * into l from public.zp_ingredient_lots where id=x.source_lot and org_id=m.org_id and site_id=p_site for update;
 if l.id is null or l.remaining_milli<x.qty_milli or (l.expires_on is not null and l.expires_on<(now() at time zone 'Africa/Douala')::date) then raise exception 'INGREDIENT_SHORTAGE';end if;
 c:=case when l.remaining_milli=x.qty_milli then l.remaining_cost else floor(l.remaining_cost::numeric*x.qty_milli/l.remaining_milli)::bigint end;
 update public.zp_ingredient_lots set remaining_milli=remaining_milli-x.qty_milli,remaining_cost=remaining_cost-c where id=l.id;
 update public.zp_transfers set state='in_transit',transferred_cost=c,expires_on=l.expires_on,source_label=l.lot_label,dispatched_at=now(),dispatched_by=m.id where id=x.id;return 'in_transit';end $$;
create function public.zp_transfer_receive(p_access text,p_site uuid,p_transfer uuid,p_qty bigint,p_reason text) returns jsonb language plpgsql security invoker set search_path=pg_catalog,public as $$
declare m public.zp_members;x public.zp_transfers;c bigint;l uuid;why text:=trim(coalesce(p_reason,''));begin m:=public.zp_transfer_actor(p_access,p_site);
 perform 1 from public.zp_site_modes where site_id=p_site for update;
 select * into x from public.zp_transfers where id=p_transfer and org_id=m.org_id and destination_site=p_site for update;if x.id is null then raise exception 'DENIED';end if;
 if x.state='received' then if (x.received_milli,x.discrepancy_reason) is distinct from (p_qty,why) then raise exception 'IDEMPOTENCY_CONFLICT';end if;return jsonb_build_object('id',x.id,'received_milli',x.received_milli,'received_cost',x.received_cost,'loss_cost',x.transferred_cost-x.received_cost);end if;
 if x.state<>'in_transit' then raise exception 'INVALID_TRANSITION';end if;
 if p_qty is null or p_qty not between 0 and x.qty_milli or length(why)>500 or (p_qty<>x.qty_milli and length(why)<5) then raise exception 'TRANSFER_COUNT_REVIEW';end if;
 if p_qty>0 and x.expires_on is not null and x.expires_on<(now() at time zone 'Africa/Douala')::date then raise exception 'EXPIRED_LOT';end if;
 c:=case when p_qty=x.qty_milli then x.transferred_cost else floor(x.transferred_cost::numeric*p_qty/x.qty_milli)::bigint end;
 if p_qty>0 then
 insert into public.zp_ingredient_lots(org_id,site_id,ingredient_id,member_id,request_id,lot_label,supplier,received_milli,remaining_milli,received_cost,remaining_cost,expires_on)
 values(m.org_id,p_site,x.destination_ingredient,m.id,gen_random_uuid(),left('TR-'||x.id::text||'-'||x.source_label,100),'Transfert interne',p_qty,p_qty,c,c,x.expires_on) returning id into l;
 end if;
 update public.zp_transfers set state='received',received_milli=p_qty,received_cost=c,destination_lot=l,discrepancy_reason=why,received_at=now(),received_by=m.id where id=x.id;
 return jsonb_build_object('id',x.id,'received_milli',p_qty,'received_cost',c,'loss_cost',x.transferred_cost-c);end $$;
create function public.zp_transfer_snapshot(p_access text,p_site uuid) returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare m public.zp_members;begin m:=public.zp_transfer_actor(p_access,p_site);
 return jsonb_build_object('sites',coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'ingredients',coalesce((select jsonb_agg(jsonb_build_object('id',i.id,'sku',i.sku,'name',i.name,'unit',i.unit)) from public.zp_ingredients i where i.org_id=m.org_id and i.site_id=s.id),'[]'::jsonb))) from public.zp_sites s join public.zp_site_scopes sc on sc.site_id=s.id and sc.org_id=s.org_id and sc.member_id=m.id join public.zp_site_modes sm on sm.site_id=s.id and sm.org_id=s.org_id where s.org_id=m.org_id and s.active and s.id<>p_site),'[]'::jsonb),'transfers',coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc) from (select id,source_site,destination_site,source_lot,destination_ingredient,qty_milli,state,transferred_cost,received_milli,received_cost,discrepancy_reason,created_at from public.zp_transfers where org_id=m.org_id and (source_site=p_site or destination_site=p_site) order by created_at desc limit 200)x),'[]'::jsonb),'site_id',p_site);end $$;
alter table public.zp_transfers enable row level security;
revoke all on public.zp_transfers from public,anon,authenticated;
grant select,insert,update,delete on public.zp_transfers to service_role;
do $$ declare f record;begin for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('zp_transfer_actor','zp_transfer_request','zp_transfer_decide','zp_transfer_dispatch','zp_transfer_receive','zp_transfer_snapshot') loop execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);end loop;end $$;
commit;
